mutants.find:
onHead: (roomId, head) => {
  hub.broadcast(roomId, { type: 'head', roomId, head });
},

return db.transaction(
  async (tx) => {
    const rows = await tx
      .select(ROW)
      .from(coreEvents)
      .where(and(eq(coreEvents.roomId, roomId), gt(coreEvents.roomSeq, roomSeq)))
      .orderBy(asc(coreEvents.roomSeq))
      .limit(limit);
    const [headRow] = await tx
      .select({ head: sql<string>`coalesce(max(${coreEvents.roomSeq}), 0)` })
      .from(coreEvents)
      .where(eq(coreEvents.roomId, roomId));

    const entries = rows.map(parseRow);
    const head = Number(headRow?.head ?? 0);
    const to = entries.at(-1)?.roomSeq ?? roomSeq;
    return { entries, head, to, more: to < head };
  },
  // REPEATABLE READ, so the two statements see one snapshot rather than
  // two consecutive ones. READ COMMITTED would take a fresh snapshot per
  // statement, which is the race this method exists to close.
  { isolationLevel: 'repeatable read', accessMode: 'read only' },
);

mutants.replace:
const rows = await db
  .select(ROW)
  .from(coreEvents)
  .where(and(eq(coreEvents.roomId, roomId), gt(coreEvents.roomSeq, roomSeq)))
  .orderBy(asc(coreEvents.roomSeq))
  .limit(limit);
const [headRow] = await db
  .select({ head: sql<string>`coalesce(max(${coreEvents.roomSeq}), 0)` })
  .from(coreEvents)
  .where(eq(coreEvents.roomId, roomId));
const entries = rows.map(parseRow);
const head = Number(headRow?.head ?? 0);
const to = entries.at(-1)?.roomSeq ?? roomSeq;
return { entries, head, to, more: entries.length === limit && to < head };

mutants.find:
journal.commit(entry.roomId, entry, entry.roomSeq);
room.events.push(entry);
room.lastSeq = entry.roomSeq;
room.head = Math.max(room.head, entry.roomSeq);

mutants.replace:
room.events.push(entry);
room.lastSeq = entry.roomSeq;
room.head = Math.max(room.head, entry.roomSeq);
journal.commit(entry.roomId, entry, entry.roomSeq);

mutants.find:
.catch((error: unknown) => {
  // Not fatal, and deliberately loud. The rows are durable, the next pass
  // will find them, and a client that noticed a gap asks for it — but a
  // *persistent* failure here means this instance has stopped delivering
  // anything a peer wrote, which is the divergence in slow motion.
  logger.error('ledger reconciliation failed', {
    error: error instanceof Error ? error.message : String(error),
  });
})
